<script setup lang="ts">
import Dialog from 'primevue/dialog'; import { useRevenueSharePolicies, type RevenueSharePolicy } from '~/composables/useRevenueSharePolicies'
definePageMeta({layout:'main',middleware:['auth','plearnd-admin']}); const {list,create,update,usage}=useRevenueSharePolicies(); const rows=ref<RevenueSharePolicy[]>([]); const loading=ref(true); const activeOnly=ref(true); const scope=ref(''); const show=ref(false); const editing=ref<RevenueSharePolicy|null>(null); const usageCount=ref<number|null>(null); const form=reactive<any>({scope_type:'platform',scope_id:null,student_pct:70,course_pct:20,platform_pct:10,effective_from:new Date().toISOString().slice(0,16),effective_to:null,notes:''}); const total=computed(()=>Number(form.student_pct||0)+Number(form.course_pct||0)+Number(form.platform_pct||0)); const load=async()=>{loading.value=true; try{const r=await list({active_only:activeOnly.value,scope_type:scope.value||undefined}); rows.value=r.data}finally{loading.value=false}}; onMounted(load); const open=(p?:RevenueSharePolicy)=>{editing.value=p||null; Object.assign(form,p?{...p,effective_from:p.effective_from.slice(0,16),effective_to:p.effective_to?.slice(0,16)}:{scope_type:'platform',scope_id:null,student_pct:70,course_pct:20,platform_pct:10,effective_from:new Date().toISOString().slice(0,16),effective_to:null,notes:''}); show.value=true}; const save=async()=>{if(total.value!==100)return; editing.value?await update(editing.value.id,form):await create(form); show.value=false; await load()}; const showUsage=async(p:RevenueSharePolicy)=>{usageCount.value=(await usage(p.id)).usage_count}
const headerText=computed(()=>editing.value?'Edit policy':'New policy')
</script>
<template><div class="mx-auto max-w-7xl space-y-6 p-6"><div class="flex items-center justify-between"><h1 class="text-2xl font-bold">{{ $t('admin.revenue_share.title') }}</h1><button class="min-h-[44px] sm:min-h-0 rounded-lg bg-primary-600 px-4 py-2 text-white" @click="open()">{{ $t('admin.revenue_share.new') }}</button></div><div class="flex gap-4"><select v-model="scope" class="rounded border p-2" @change="load"><option value="">All scopes</option><option>platform</option><option>academy</option><option>course</option><option>campaign</option></select><label class="flex items-center gap-2"><input v-model="activeOnly" type="checkbox" @change="load"> {{ $t('admin.revenue_share.active_only') }}</label></div><div class="overflow-auto rounded-2xl bg-white shadow"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">ID</th><th>Scope</th><th>Student / Course / Platform</th><th>Effective</th><th>Version</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in rows" :key="p.id" class="border-t"><td class="p-3">{{p.id}}</td><td>{{p.scope_type}} {{p.scope_id||''}}</td><td>{{p.student_pct}} / {{p.course_pct}} / {{p.platform_pct}}</td><td>{{p.effective_from}} → {{p.effective_to||'∞'}}</td><td>{{p.version}}</td><td><span :class="p.is_active?'text-emerald-600':'text-slate-500'">{{p.is_active?'Active':'Inactive'}}</span></td><td><button class="mr-2 text-primary-600" @click="open(p)">Edit</button><button class="text-primary-600" @click="showUsage(p)">Usage</button></td></tr><tr v-if="!loading&&!rows.length"><td colspan="7" class="p-8 text-center">No policies</td></tr></tbody></table></div><Dialog v-model:visible="show" modal :header="headerText" class="w-full max-w-lg"><div class="grid gap-3"><select v-model="form.scope_type" class="rounded border p-2"><option>platform</option><option>academy</option><option>course</option><option>campaign</option></select><input v-model.number="form.scope_id" type="number" placeholder="Scope ID (optional for platform)" class="rounded border p-2"><div class="grid grid-cols-3 gap-2"><input v-model.number="form.student_pct" type="number" class="rounded border p-2"><input v-model.number="form.course_pct" type="number" class="rounded border p-2"><input v-model.number="form.platform_pct" type="number" class="rounded border p-2"></div><p v-if="total!==100" class="text-sm text-red-600">Percentages must sum to 100 (currently {{total}}).</p><input v-model="form.effective_from" type="datetime-local" class="rounded border p-2"><input v-model="form.effective_to" type="datetime-local" class="rounded border p-2"><textarea v-model="form.notes" maxlength="500" class="rounded border p-2" placeholder="Notes"/><button :disabled="total!==100" class="min-h-[44px] sm:min-h-0 rounded bg-primary-600 p-2 text-white disabled:opacity-50" @click="save">Save</button></div></Dialog><Dialog :visible="usageCount!==null" modal header="Policy usage" @update:visible="usageCount=null"><p>{{ $t('admin.revenue_share.usage_count', {count:usageCount}) }}</p></Dialog></div></template>
